.mstep b{font-weight:500}
.mstep.done{color:var(--muted)} .mstep.done b{color:var(--text)}
.mstep.done .d{background:var(--mint);box-shadow:none;color:#fff;transform:scale(1.05)}
.mstep.now{background:var(--accent-soft);color:var(--muted)} .mstep.now b{color:var(--text)}
.mstep.now .d{background:var(--accent);color:#fff;box-shadow:0 0 0 6px rgba(91,75,255,.15);animation:ring 1.6s infinite}
@keyframes ring{50%{box-shadow:0 0 0 10px rgba(91,75,255,.03)}}
.typing{margin-top:14px;padding:14px 16px;border-radius:18px;background:var(--bg);font-size:14px;min-height:86px}
.typing .caret{display:inline-block;width:2px;height:1em;background:var(--accent);vertical-align:-2px;margin-left:2px;animation:blink 1s infinite}
.mock-f{display:flex;justify-content:space-between;align-items:center;margin-top:16px;padding-top:14px;border-top:1px solid var(--line);font-size:13px;color:var(--faint)}
.float{position:absolute;padding:12px 14px;border-radius:18px;font-size:13px;background:rgba(255,255,255,.92);backdrop-filter:blur(12px);box-shadow:var(--shadow-m),0 0 0 1px var(--line);display:flex;gap:10px;align-items:center;transform:translateZ(70px);transition:opacity .5s}
.float.f1{top:-24px;right:-8px;animation:bob 6s ease-in-out infinite}
.float.f2{bottom:-24px;left:-28px;animation:bob 7s ease-in-out -2s infinite}
.float.f3{top:44%;right:-40px;animation:bob 8s ease-in-out -4s infinite}
@keyframes bob{50%{translate:0 -10px}}
.ok-burst{animation:burst .9s ease}
@keyframes burst{0%{box-shadow:0 0 0 0 rgba(16,148,108,.45),var(--shadow-m)}100%{box-shadow:0 0 0 30px rgba(16,148,108,0),var(--shadow-m)}}
@media (max-width:980px){.stage{min-height:0;margin-top:10px}.float{display:none}.tilt{transform:none}}

      <div class="stage" id="stage"><div class="tilt" id="tilt">
