          <div class="msteps" id="mSteps"></div>
          <div class="typing" id="mType"></div>
          <div class="mock-f"><span>до автовозврата</span><span class="mono" style="color:var(--text)" id="mTimer">41:12:09</span></div>
        </div>
        <div class="float f1"><span class="star">★</span><span><b>4,9</b> · 38 разборов</span></div>
        <div class="float f2" id="fOk"><span class="pill mint">Рекомендован</span><span class="faint small">рекрутеру Яндекса</span></div>
        <div class="float f3"><span class="verified" style="margin:0">@yandex-team.ru подтверждена</span></div>
