async (page) => {
  await page.setViewportSize({width:390,height:844});
  await page.goto('https://izn-site.vercel.app',{waitUntil:'networkidle'});
  return await page.evaluate(()=>{
    const r=[];
    document.querySelectorAll('.v-chips').forEach(c=>{const p=c.closest('.fvis-m')||c.parentElement;const cr=c.getBoundingClientRect(),pr=p.getBoundingClientRect(); r.push({cls:p.className, chipsR:Math.round(cr.right), parentR:Math.round(pr.right), last:Math.round(c.lastElementChild.getBoundingClientRect().right), sw:c.scrollWidth, cw:c.clientWidth, disp:getComputedStyle(c).flexWrap})});
    const bad=[...document.querySelectorAll('body *')].filter(e=>{if(e.closest('.marq'))return false;const s=getComputedStyle(e);if(s.display==='none')return false;return e.scrollWidth>e.clientWidth+2 && s.overflowX!=='visible' && e.clientWidth>0}).slice(0,15).map(e=>[e.tagName,e.className.toString().slice(0,50),e.scrollWidth,e.clientWidth, (e.textContent||'').trim().slice(0,40)]);
    return {r,bad};
  });
}

