async (page) => {
  await page.setViewportSize({width:1280,height:900});
  await page.goto('http://localhost:8765/?v='+Date.now(),{waitUntil:'networkidle'});
  const sel = page.locator('select[name=func]');
  await sel.scrollIntoViewIfNeeded(); await page.waitForTimeout(800);
  const r = await page.evaluate(()=>{const s=document.querySelector('select[name=func]');const i=s.closest('form').querySelector('input.input');const a=s.getBoundingClientRect(),b=i.getBoundingClientRect();return {sel:[Math.round(a.top),Math.round(a.height)],inp:[Math.round(b.top),Math.round(b.height)]}});
  await page.locator('.jbox, form').first().screenshot({path:'../../vp/fix_select.jpg',type:'jpeg',quality:70});
  return r;
}

